1	/**
2	 * 执行队列：FIFO 排序、仅队首可执行、终态不可逆、执行幂等。
3	 *
4	 * 队列本身不关心任务内容：准入校验由钱包引擎完成；执行语义由执行器回调提供。
5	 * 任务 id 由入队序号与任务摘要派生，保证同一引擎内可复现、可引用。
6	 */
7	
8	import { createHash } from 'node:crypto';
9	import { InvalidQueueStateError, TaskNotFoundError } from './errors.ts';
10	
11	export type TaskStatus = 'queued' | 'executed' | 'failed';
12	
13	export interface QueueTask<P = unknown> {
14	  id: string;
15	  /** 入队序号，从 0 起严格递增；同时决定执行顺序 */
16	  seq: number;
17	  nonce: bigint;
18	  status: TaskStatus;
19	  submittedAt: bigint;
20	  /** 签名摘要（域分隔），作为队列层面的防重指纹 */
21	  digest: string;
22	  payload: P;
23	  receipt?: ExecutionReceipt;
24	}
25	
26	export interface ExecutionReceipt {
27	  status: Extract<TaskStatus, 'executed' | 'failed'>;
28	  /** 失败时为错误名称（如 PolicyConflict / RequestExpired），成功时为 null */
29	  failureReason: string | null;
30	  failureMessage: string | null;
31	  executedAt: bigint;
32	  /** 成功执行的输出（执行器回调返回） */
33	  result?: unknown;
34	}
35	
36	/**
37	 * 执行器：对队首任务做实际生效处理。
38	 * 抛错 → 任务进入 failed 终态（错误名称写入回执）；正常返回 → executed 终态。
39	 */
40	export type Executor<P> = (task: QueueTask<P>) => unknown;
41	
42	export class ExecutionQueue<P = unknown> {
43	  private readonly tasks: QueueTask<P>[] = [];
44	  private head = 0;
45	  private readonly executor: Executor<P>;
46	
47	  constructor(executor: Executor<P>) {
48	    this.executor = executor;
49	  }
50	
51	  /**
52	   * 入队（FIFO 尾部）。
53	   * digest 是任务内容的唯一承诺：在全部历史任务（含失败终态）上都不得重复。
54	   * 失败任务的 nonce 已被消费，其摘要重现本就会被上层 nonce 防护拦截，这里再兜一层，
55	   * 保证队列层面的严格防重。
56	   */
57	  enqueue(input: { nonce: bigint; digest: string; payload: P; submittedAt: bigint }): QueueTask<P> {
58	    if (this.tasks.some((t) => t.digest === input.digest)) {
59	      throw new InvalidQueueStateError(`duplicate task digest: ${input.digest}`);
60	    }
61	    const seq = this.tasks.length;
62	    const task: QueueTask<P> = {
63	      id: createHash('sha256').update(`${seq}:${input.digest}`).digest('hex').slice(0, 16),
64	      seq,
65	      nonce: input.nonce,
66	      status: 'queued',
67	      submittedAt: input.submittedAt,
68	      digest: input.digest,
69	      payload: input.payload,
70	    };
71	    this.tasks.push(task);
72	    return task;
73	  }
74	
75	  /** 队首任务；队列空或队首已终态时为 null */
76	  peekHead(): QueueTask<P> | null {
77	    return this.head < this.tasks.length ? (this.tasks[this.head] ?? null) : null;
78	  }
79	
80	  /**
81	   * 执行指定任务。
82	   * - 仅队首可执行（保证排序/nonce 语义）；
83	   * - 终态任务重复调用直接返回既有回执，不重复生效（幂等）；
84	   * - 不存在的 id 抛 TaskNotFoundError；非队首的待执行任务抛 InvalidQueueStateError。
85	   */
86	  execute(id: string, now: bigint): QueueTask<P> {
87	    const task = this.tasks.find((t) => t.id === id);
88	    if (task === undefined) throw new TaskNotFoundError(`task not found: ${id}`);
89	    if (task.status !== 'queued') return task; // 幂等：回放终态回执
90	    if (task.seq !== this.head) {
91	      throw new InvalidQueueStateError(`task ${id} is not at queue head`);
92	    }
93	
94	    try {
95	      const result = this.executor(task);
96	      task.receipt = { status: 'executed', failureReason: null, failureMessage: null, executedAt: now, result };
97	      task.status = 'executed';
98	    } catch (err) {
99	      const e = err as Error;
100	      task.receipt = { status: 'failed', failureReason: e.name, failureMessage: e.message, executedAt: now };
101	      task.status = 'failed';
102	    }
103	    this.head += 1;
104	    return task;
105	  }
106	
107	  /** 执行当前队首；队列已排空时返回 null */
108	  executeNext(now: bigint): QueueTask<P> | null {
109	    const head = this.peekHead();
110	    if (head === null) return null;
111	    return this.execute(head.id, now);
112	  }
113	
114	  getTask(id: string): QueueTask<P> | null {
115	    return this.tasks.find((t) => t.id === id) ?? null;
116	  }
117	
118	  /** 队列快照（按入队顺序），任务在执行前后均可见 */
119	  listTasks(): readonly QueueTask<P>[] {
120	    return this.tasks;
121	  }
122	
123	  get size(): number {
124	    return this.tasks.length;
125	  }
126	}
