1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护与 FIFO 执行队列之上，新增“策略变更任务”：
5	 * 所有者以当前阈值签名，决定替换所有者集合、确认数；任务入队，按既有排序/防重/
6	 * 终态规则执行；执行成功才原子替换策略并令版本递增一次，执行时版本漂移则
7	 * PolicyConflict 进入既有失败终态。
8	 */
9	
10	import {
11	  type Address,
12	  ZERO_ADDRESS,
13	  isZeroAddress,
14	  normalizeAddress,
15	  recoverAddress,
16	} from './crypto.ts';
17	import {
18	  hashPolicyChange,
19	  hashTransaction,
20	  type PolicyChangeRequest,
21	  type TransactionRequest,
22	} from './encoding.ts';
23	import {
24	  InvalidPolicyChange,
25	  InvalidTransaction,
26	  NonceAlreadyUsedError,
27	  RequestExpired,
28	  PolicyConflict,
29	  InvalidQueueStateError,
30	} from './errors.ts';
31	import { ExecutionQueue, type QueueTask } from './queue.ts';
32	
33	// ---------- 任务载荷 ----------
34	
35	export type WalletTaskPayload =
36	  | {
37	      kind: 'transaction';
38	      deadline: bigint;
39	      to: Address;
40	      value: bigint;
41	      data: Uint8Array;
42	    }
43	  | {
44	      kind: 'policy-change';
45	      deadline: bigint;
46	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
47	      version: bigint;
48	      newOwners: Address[];
49	      newConfirmations: bigint;
50	    };
51	
52	export type WalletTask = QueueTask<WalletTaskPayload>;
53	
54	export interface PolicyState {
55	  owners: Address[];
56	  confirmations: bigint;
57	  version: bigint;
58	}
59	
60	export interface WalletOptions {
61	  id: string;
62	  owners: Address[];
63	  confirmations: bigint | number;
64	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
65	  now?: () => bigint;
66	}
67	
68	export interface TransactionSubmission {
69	  nonce: bigint | number;
70	  deadline: bigint | number;
71	  to: string;
72	  value: bigint | number;
73	  data?: Uint8Array;
74	}
75	
76	export interface PolicyChangeSubmission {
77	  version: bigint | number;
78	  nonce: bigint | number;
79	  deadline: bigint | number;
80	  newOwners: string[];
81	  newConfirmations: bigint | number;
82	}
83	
84	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
85	  return n >= 0n && n < 2n ** BigInt(maxBits);
86	}
87	
88	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
89	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
90	  if (typeof value === 'bigint') return value;
91	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
92	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
93	  throw new Invalid(`field "${field}" must be a non-negative integer`);
94	}
95	
96	export class MultiSigWallet {
97	  readonly id: string;
98	  private readonly now: () => bigint;
99	
100	  private owners: Address[];
101	  private readonly ownerSet: Set<Address>;
102	  private confirmations: bigint;
103	  private version: bigint;
104	
105	  /** 下一个期望 nonce（严格递增，顺序提交） */
106	  private nextNonce = 0n;
107	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
108	  private readonly usedNonces = new Set<bigint>();
109	
110	  readonly queue: ExecutionQueue<WalletTaskPayload>;
111	
112	  constructor(opts: WalletOptions) {
113	    const owners = normalizeOwnerList(opts.owners);
114	    const confirmations = BigInt(opts.confirmations);
115	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
116	      throw new InvalidPolicyChange(
117	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
118	      );
119	    }
120	    this.id = opts.id;
121	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
122	    this.owners = owners;
123	    this.ownerSet = new Set(owners);
124	    this.confirmations = confirmations;
125	    this.version = 1n;
126	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
127	  }
128	
129	  // ---------- 只读状态 ----------
130	
131	  get policy(): PolicyState {
132	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
133	  }
134	
135	  get policyVersion(): bigint {
136	    return this.version;
137	  }
138	
139	  get currentOwners(): Address[] {
140	    return [...this.owners];
141	  }
142	
143	  get requiredConfirmations(): bigint {
144	    return this.confirmations;
145	  }
146	
147	  get expectedNonce(): bigint {
148	    return this.nextNonce;
149	  }
150	
151	  isOwner(address: string): boolean {
152	    const a = normalizeAddress(address);
153	    return a !== null && this.ownerSet.has(a);
154	  }
155	
156	  isNonceUsed(nonce: bigint | number): boolean {
157	    return this.usedNonces.has(BigInt(nonce));
158	  }
159	
160	  get tasks(): readonly WalletTask[] {
161	    return this.queue.listTasks();
162	  }
163	
164	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
165	
166	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
167	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
168	    return this.submit(
169	      'transaction',
170	      {
171	        nonce: sub.nonce,
172	        deadline: sub.deadline,
173	        to: sub.to,
174	        value: sub.value,
175	        data: sub.data ?? new Uint8Array(),
176	      },
177	      signatures,
178	    );
179	  }
180	
181	  // ---------- 策略变更提交 ----------
182	
183	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
184	    return this.submit(
185	      'policy-change',
186	      {
187	        version: sub.version,
188	        nonce: sub.nonce,
189	        deadline: sub.deadline,
190	        newOwners: sub.newOwners,
191	        newConfirmations: sub.newConfirmations,
192	      },
193	      signatures,
194	    );
195	  }
196	
197	  // ---------- 执行 ----------
198	
199	  executeTask(taskId: string): WalletTask {
200	    return this.queue.execute(taskId, this.now());
201	  }
202	
203	  executeNext(): WalletTask | null {
204	    return this.queue.executeNext(this.now());
205	  }
206	
207	  getTask(taskId: string): WalletTask | null {
208	    return this.queue.getTask(taskId);
209	  }
210	
211	  // ============================================================
212	  // 内部实现
213	  // ============================================================
214	
215	  /**
216	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
217	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
218	   */
219	  private submit(
220	    kind: WalletTaskPayload['kind'],
221	    raw: Record<string, unknown>,
222	    signatures: readonly Uint8Array[],
223	  ): WalletTask {
224	    const Invalid = kind === 'policy-change' ? InvalidPolicyChange : InvalidTransaction;
225	
226	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
227	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
228	    //   2) 截止时间早于当前时间 → RequestExpired
229	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
230	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
231	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
232	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
233	
234	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
235	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
236	    if (deadline < this.now()) {
237	      throw new RequestExpired(`request deadline ${deadline} already passed`);
238	    }
239	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
240	
241	    // (3) 字段校验 + 规范化
242	    let payload: WalletTaskPayload;
243	    let digest: Buffer;
244	    if (kind === 'transaction') {
245	      const to = normalizeAddress(raw.to as string);
246	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
247	      const value = toBigInt(raw.value, Invalid, 'value');
248	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
249	      const dataField = raw.data;
250	      if (
251	        dataField !== undefined &&
252	        !(dataField instanceof Uint8Array) &&
253	        !ArrayBuffer.isView(dataField)
254	      ) {
255	        throw new Invalid('data must be a byte array');
256	      }
257	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
258	      const req: TransactionRequest = {
259	        walletId: this.id,
260	        nonce,
261	        deadline,
262	        to,
263	        value,
264	        data,
265	      };
266	      digest = hashTransaction(req);
267	      payload = { kind: 'transaction', deadline, to, value, data };
268	    } else {
269	      const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
270	      // (3a) 版本必须绑定当前版本（提交时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
271	      if (version !== this.version) {
272	        throw new InvalidPolicyChange(
273	          `policy version mismatch: bound ${version}, current ${this.version}`,
274	        );
275	      }
276	      // (3b) 以当前版本为基准验证新策略
277	      const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
278	      const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
279	      if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
280	        throw new InvalidPolicyChange(
281	          `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
282	        );
283	      }
284	      const req: PolicyChangeRequest = {
285	        walletId: this.id,
286	        version,
287	        nonce,
288	        deadline,
289	        newOwners,
290	        newConfirmations,
291	      };
292	      digest = hashPolicyChange(req);
293	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
294	    }
295	
296	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
297	    this.verifyThresholdSignatures(digest, signatures, Invalid);
298	
299	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
300	    //     入队失败（同一摘要重复等）时不消费 nonce。
301	    let task: WalletTask;
302	    try {
303	      task = this.queue.enqueue({
304	        nonce,
305	        digest: digest.toString('hex'),
306	        payload,
307	        submittedAt: this.now(),
308	      });
309	    } catch (err) {
310	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
311	      throw err;
312	    }
313	    this.usedNonces.add(nonce);
314	    this.nextNonce = nonce + 1n;
315	    return task;
316	  }
317	
318	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
319	  private verifyThresholdSignatures(
320	    digest: Uint8Array,
321	    signatures: readonly Uint8Array[],
322	    Invalid: typeof InvalidPolicyChange,
323	  ): void {
324	    if (!Array.isArray(signatures)) {
325	      throw new Invalid('signatures must be an array');
326	    }
327	    if (signatures.length === 0) throw new Invalid('missing signatures');
328	
329	    const signedBy = new Set<Address>();
330	    for (const sig of signatures) {
331	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
332	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
333	      }
334	      const signer = recoverAddress(digest, Uint8Array.from(sig));
335	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
336	      if (!this.ownerSet.has(signer)) {
337	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
338	        throw new Invalid('signature does not match payload or signer is not an owner');
339	      }
340	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
341	    }
342	    if (BigInt(signedBy.size) < this.confirmations) {
343	      throw new Invalid(
344	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
345	      );
346	    }
347	  }
348	
349	  /** 队列执行器回调：定义两类任务的生效语义 */
350	  private applyTask(task: WalletTask): unknown {
351	    const p = task.payload;
352	    if (p.kind === 'transaction') {
353	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
354	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
355	      return {
356	        kind: 'transfer',
357	        to: p.to,
358	        value: p.value,
359	        data: Buffer.from(p.data).toString('hex'),
360	      };
361	    }
362	
363	    // 策略变更：仅当绑定版本仍等于当前版本时生效
364	    if (p.version !== this.version) {
365	      throw new PolicyConflict(
366	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
367	      );
368	    }
369	    // 所有者集合与确认数同时替换；版本恰好递增一次
370	    this.owners = [...p.newOwners];
371	    this.ownerSet.clear();
372	    for (const o of this.owners) this.ownerSet.add(o);
373	    this.confirmations = p.newConfirmations;
374	    this.version += 1n;
375	    return {
376	      kind: 'policy-applied',
377	      version: this.version,
378	      owners: [...this.owners],
379	      confirmations: this.confirmations,
380	    };
381	  }
382	}
383	
384	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
385	
386	function normalizeOwnerList(
387	  input: readonly string[],
388	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
389	): Address[] {
390	  if (!Array.isArray(input) || input.length === 0) {
391	    throw new ErrorCtor('owners list must be a non-empty array');
392	  }
393	  const out: Address[] = [];
394	  const seen = new Set<Address>();
395	  for (const raw of input) {
396	    const addr = normalizeAddress(raw);
397	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
398	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
399	      throw new ErrorCtor('zero address is not allowed as owner');
400	    }
