1	/**
2	 * 规范化编码与签名摘要。
3	 *
4	 * 两类操作使用不同的域分隔标签，签名互不兼容（普通交易签名不能用于策略变更，反之亦然）：
5	 *   - 普通交易：   "safe-wallet/tx/v1"
6	 *   - 策略变更：   "safe-wallet/policy-change/v1"
7	 *
8	 * 编码规则（全部大端）：
9	 *   encBytes(b)  = uint32(len) || b
10	 *   encStr(s)    = uint32(len) || utf8(s)
11	 *   encUint(n)   = n 的定长 32 字节大端表示
12	 *   encList(xs)  = uint32(count) || concat(encBytes(x))
13	 *
14	 * 普通交易载荷不包含策略版本字段（保持既有交易格式不变）；
15	 * 策略变更载荷显式绑定钱包标识、操作标签、当前版本、新所有者、新确认数、nonce、截止时间。
16	 */
17	
18	import { sha256, hexToBytes, type Address } from './crypto.ts';
19	
20	const TAG_TX = 'safe-wallet/tx/v1';
21	const TAG_POLICY_CHANGE = 'safe-wallet/policy-change/v1';
22	
23	// ---------- 编码原语 ----------
24	
25	export function encBytes(data: Uint8Array): Buffer {
26	  const b = Buffer.from(data);
27	  const out = Buffer.alloc(4 + b.length);
28	  out.writeUInt32BE(b.length, 0);
29	  b.copy(out, 4);
30	  return out;
31	}
32	
33	export function encStr(s: string): Buffer {
34	  return encBytes(Buffer.from(s, 'utf8'));
35	}
36	
37	export function encUint(n: bigint | number): Buffer {
38	  const v = BigInt(n);
39	  if (v < 0n) throw new Error('cannot encode negative integer');
40	  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
41	  const out = Buffer.alloc(32);
42	  let x = v;
43	  for (let i = 31; i >= 0; i--) {
44	    out[i] = Number(x & 0xffn);
45	    x >>= 8n;
46	  }
47	  return out;
48	}
49	
50	export function encList(items: Uint8Array[]): Buffer {
51	  const head = Buffer.alloc(4);
52	  head.writeUInt32BE(items.length, 0);
53	  return Buffer.concat([head, ...items.map(encBytes)]);
54	}
55	
56	function digest(tag: string, parts: Buffer[]): Buffer {
57	  return sha256(Buffer.concat([encStr(tag), ...parts]));
58	}
59	
60	// ---------- 请求类型 ----------
61	
62	export interface TransactionRequest {
63	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
64	  walletId: string;
65	  nonce: bigint;
66	  /** Unix 秒级截止时间（也接受毫秒级大数；语义由调用方约定，引擎按数值比较） */
67	  deadline: bigint;
68	  to: Address;
69	  value: bigint;
70	  data: Uint8Array;
71	}
72	
73	export interface PolicyChangeRequest {
74	  walletId: string;
75	  /** 提交时绑定的当前策略版本 */
76	  version: bigint;
77	  nonce: bigint;
78	  deadline: bigint;
79	  newOwners: Address[];
80	  newConfirmations: bigint;
81	}
82	
83	function walletIdBytes(walletId: string): Buffer {
84	  // 钱包标识统一按 UTF-8 参与签名绑定（任意字符串均可）
85	  return Buffer.from(walletId, 'utf8');
86	}
87	
88	function deadlineToBigint(d: bigint | number): bigint {
89	  return BigInt(d);
90	}
91	
92	/** 普通交易的签名摘要（不含策略版本字段） */
93	export function hashTransaction(req: {
94	  walletId: string;
95	  nonce: bigint | number;
96	  deadline: bigint | number;
97	  to: Address;
98	  value: bigint | number;
99	  data: Uint8Array;
100	}): Buffer {
101	  return digest(TAG_TX, [
102	    encBytes(walletIdBytes(req.walletId)),
103	    encUint(req.nonce),
104	    encUint(deadlineToBigint(req.deadline)),
105	    encBytes(hexToBytes(req.to)),
106	    encUint(req.value),
107	    encBytes(req.data),
108	  ]);
109	}
110	
111	/** 策略变更的签名摘要：显式绑定版本、新所有者与新确认数 */
112	export function hashPolicyChange(req: {
113	  walletId: string;
114	  version: bigint | number;
115	  nonce: bigint | number;
116	  deadline: bigint | number;
117	  newOwners: Address[];
118	  newConfirmations: bigint | number;
119	}): Buffer {
120	  return digest(TAG_POLICY_CHANGE, [
121	    encBytes(walletIdBytes(req.walletId)),
122	    encUint(req.version),
123	    encUint(req.nonce),
124	    encUint(deadlineToBigint(req.deadline)),
125	    encUint(req.newConfirmations),
126	    encList(req.newOwners.map((o) => hexToBytes(o))),
127	  ]);
128	}
