1	/**
2	 * 零依赖密码学原语：
3	 * - SHA-256（基于 node:crypto 的摘要/HMAC）
4	 * - secp256k1 点运算、RFC 6979 确定性 ECDSA 签名、公钥恢复
5	 * - 地址 = SHA-256(未压缩公钥 65 字节) 的末 20 字节（0x 前缀 EIP-55 之外的小写十六进制）
6	 *
7	 * 签名统一为 65 字节：r(32) || s(32) || v(1)，其中 v 为公钥恢复标识（0..3）。
8	 * 所有产出签名强制 low-s（s <= N/2），天然具备抗可塑性。
9	 */
10	
11	import { createHash, createHmac, randomBytes } from 'node:crypto';
12	
13	// ---------- 基础类型 ----------
14	
15	/** 0x 开头的 40 位小写十六进制地址 */
16	export type Address = string;
17	
18	export const ZERO_ADDRESS: Address = '0x' + '00'.repeat(20);
19	
20	export function sha256(data: Uint8Array): Buffer {
21	  return createHash('sha256').update(data).digest();
22	}
23	
24	export function hexToBytes(hex: string): Buffer {
25	  if (typeof hex !== 'string') throw new TypeError('hex value must be a string');
26	  const h = hex.startsWith('0x') ? hex.slice(2) : hex;
27	  if (!/^[0-9a-fA-F]*$/.test(h) || h.length % 2 !== 0) {
28	    throw new Error(`invalid hex string: ${hex}`);
29	  }
30	  return Buffer.from(h, 'hex');
31	}
32	
33	export function bytesToHex(bytes: Uint8Array): string {
34	  return '0x' + Buffer.from(bytes).toString('hex');
35	}
36	
37	/** 规范化为 0x + 小写；非法返回 null */
38	export function normalizeAddress(value: string): Address | null {
39	  if (typeof value !== 'string') return null;
40	  const h = value.startsWith('0x') ? value.slice(2) : null;
41	  if (h === null || h.length !== 40 || !/^[0-9a-fA-F]{40}$/.test(h)) return null;
42	  return ('0x' + h.toLowerCase()) as Address;
43	}
44	
45	export function isZeroAddress(addr: Address): boolean {
46	  return addr === ZERO_ADDRESS;
47	}
48	
49	// ---------- secp256k1 曲线参数 ----------
50	
51	const P = 2n ** 256n - 2n ** 32n - 977n;
52	const N = BigInt('0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141');
53	const HALF_N = N >> 1n;
54	const Gx = BigInt('55066263022277343669578718895168534326250603453777594175500187360389116729240');
55	const Gy = BigInt('32670510020758816978083085130507043184471273380659243275938904335757337482424');
56	
57	type Jacobian = { x: bigint; y: bigint; z: bigint } | null;
58	type Affine = { x: bigint; y: bigint } | null;
59	
60	const mod = (a: bigint): bigint => ((a % P) + P) % P;
61	const modN = (a: bigint): bigint => ((a % N) + N) % N;
62	
63	function invMod(a: bigint, m: bigint): bigint {
64	  let [oldR, r] = [((a % m) + m) % m, m];
65	  let [oldS, s] = [1n, 0n];
66	  while (r !== 0n) {
67	    const q = oldR / r;
68	    [oldR, r] = [r, oldR - q * r];
69	    [oldS, s] = [s, oldS - q * s];
70	  }
71	  if (oldR !== 1n) throw new Error('no modular inverse');
72	  return ((oldS % m) + m) % m;
73	}
74	
75	function toAffine(p: Jacobian): Affine {
76	  if (p === null) return null;
77	  if (p.z === 0n) return null;
78	  const zi = invMod(p.z, P);
79	  const zi2 = mod(zi * zi);
80	  const zi3 = mod(zi2 * zi);
81	  return { x: mod(p.x * zi2), y: mod(p.y * zi3) };
82	}
83	
84	/** Jacobian 点倍加（a=0 曲线） */
85	function jacDouble(p: Jacobian): Jacobian {
86	  if (p === null || p.y === 0n) return null;
87	  const y2 = mod(p.y * p.y);
88	  const y4 = mod(y2 * y2);
89	  const s = mod(4n * p.x * y2);
90	  const m = mod(3n * p.x * p.x);
91	  const x3 = mod(m * m - 2n * s);
92	  const y3 = mod(m * (s - x3) - 8n * y4);
93	  const z3 = mod(2n * p.y * p.z);
94	  return { x: x3, y: y3, z: z3 };
95	}
96	
97	/** Jacobian P + 仿射 Q（mixed addition） */
98	function jacAddAffine(p: Jacobian, q: { x: bigint; y: bigint }): Jacobian {
99	  if (p === null) return { x: q.x, y: q.y, z: 1n };
100	  const z1z1 = mod(p.z * p.z);
101	  const u2 = mod(q.x * z1z1);
102	  const s2 = mod(q.y * z1z1 * p.z);
103	  if (u2 === p.x) {
104	    if (s2 !== p.y) return null;
105	    return jacDouble(p);
106	  }
107	  const h = mod(u2 - p.x);
108	  const hh = mod(h * h);
109	  const i = mod(4n * hh);
110	  const j = mod(h * i);
111	  const r = mod(2n * (s2 - p.y));
112	  const v = mod(p.x * i);
113	  const x3 = mod(r * r - j - 2n * v);
114	  const y3 = mod(r * (v - x3) - 2n * p.y * j);
115	  const z3 = mod((p.z + h) * (p.z + h) - z1z1 - hh);
116	  return { x: x3, y: y3, z: z3 };
117	}
118	
119	/** 标量乘仿射点（double-and-add） */
120	function scalarMul(k: bigint, point: { x: bigint; y: bigint }): Jacobian {
121	  let n = ((k % N) + N) % N;
122	  let result: Jacobian = null;
123	  let addend: Jacobian = { x: point.x, y: point.y, z: 1n };
124	  while (n > 0n) {
125	    if (n & 1n) result = jacAddAffine(result, toAffine(addend)!);
126	    addend = jacDouble(addend);
127	    n >>= 1n;
128	  }
129	  return result;
130	}
131	
132	const G = { x: Gx, y: Gy };
133	
134	// ---------- 整数 / 定长字节 ----------
135	
136	function bytesToBigInt(bytes: Uint8Array): bigint {
137	  let n = 0n;
138	  for (const b of bytes) n = (n << 8n) | BigInt(b);
139	  return n;
140	}
141	
142	function bigIntToBytes(n: bigint, length: number): Buffer {
143	  const out = Buffer.alloc(length);
144	  let v = n;
145	  for (let i = length - 1; i >= 0; i--) {
146	    out[i] = Number(v & 0xffn);
147	    v >>= 8n;
148	  }
149	  return out;
150	}
151	
152	function to32(n: bigint): Buffer {
153	  return bigIntToBytes(n, 32);
154	}
155	
156	// ---------- 密钥与地址 ----------
157	
158	export interface KeyPair {
159	  /** 32 字节私钥标量（大端） */
160	  privateKey: Buffer;
161	  /** 65 字节未压缩公钥 0x04 || X || Y */
162	  publicKey: Buffer;
163	  address: Address;
164	}
165	
166	export function publicKeyFromScalar(d: bigint): Buffer {
167	  if (d <= 0n || d >= N) throw new Error('private scalar out of range');
168	  const q = toAffine(scalarMul(d, G))!;
169	  return Buffer.concat([Buffer.from([0x04]), to32(q.x), to32(q.y)]);
170	}
171	
172	export function addressFromPublicKey(publicKey: Uint8Array): Address {
173	  const pk = Buffer.from(publicKey);
174	  if (pk.length !== 65 || pk[0] !== 0x04) throw new Error('expected 65-byte uncompressed public key');
175	  return bytesToHex(sha256(pk).subarray(12)) as Address;
176	}
177	
178	export function generateKeyPair(): KeyPair {
179	  let d: bigint;
180	  do {
181	    d = bytesToBigInt(randomBytes(32)) % N;
182	  } while (d === 0n);
183	  const publicKey = publicKeyFromScalar(d);
184	  return { privateKey: to32(d), publicKey, address: addressFromPublicKey(publicKey) };
185	}
186	
187	/** 由 32 字节私钥重建密钥对（测试/钱包导入用） */
188	export function keyPairFromPrivate(privateKey: Uint8Array): KeyPair {
189	  const sk = Buffer.from(privateKey);
190	  if (sk.length !== 32) throw new Error('private key must be 32 bytes');
191	  const d = bytesToBigInt(sk);
192	  const publicKey = publicKeyFromScalar(d);
193	  return { privateKey: sk, publicKey, address: addressFromPublicKey(publicKey) };
194	}
195	
196	// ---------- RFC 6979 确定性 nonce ----------
197	
198	function rfc6979K(d: bigint, e: bigint): () => bigint {
199	  const x = to32(d);
200	  const h1 = to32(e);
201	  let v = Buffer.alloc(32, 0x01);
202	  let k = Buffer.alloc(32, 0x00);
203	  const hmac = () => createHmac('sha256', k).update(v).digest();
204	  k = createHmac('sha256', k).update(Buffer.concat([v, Buffer.from([0x00]), x, h1])).digest();
205	  v = hmac();
206	  k = createHmac('sha256', k).update(Buffer.concat([v, Buffer.from([0x01]), x, h1])).digest();
207	  v = hmac();
208	  // 此时 v 即第一个候选 T；每次取出后按 RFC 推进 K、V
209	  return () => {
210	    const candidate = bytesToBigInt(v);
211	    k = createHmac('sha256', k).update(Buffer.concat([v, Buffer.from([0x00])])).digest();
212	    v = hmac();
213	    return candidate;
214	  };
215	}
216	
217	// ---------- 公钥恢复 ----------
218	
219	function decompressPoint(x: bigint, oddY: boolean): { x: bigint; y: bigint } | null {
220	  if (x >= P) return null;
221	  const alpha = mod(x * x * x + 7n);
222	  // p ≡ 3 (mod 4)
223	  let y = modPow(alpha, (P + 1n) / 4n, P);
224	  if (mod(y * y) !== alpha) return null;
225	  if ((y & 1n) === (oddY ? 0n : 1n)) y = P - y;
226	  return { x, y };
227	}
228	
229	function modPow(base: bigint, exp: bigint, m: bigint): bigint {
230	  let result = 1n;
231	  let b = ((base % m) + m) % m;
232	  let e = exp;
233	  while (e > 0n) {
234	    if (e & 1n) result = (result * b) % m;
235	    b = (b * b) % m;
236	    e >>= 1n;
237	  }
238	  return result;
239	}
240	
241	export interface RecoveredSignature {
242	  r: bigint;
243	  s: bigint;
244	  recoveryId: number;
245	}
246	
247	/** 解析 65 字节签名并做范围/规范性检查（low-s） */
248	export function parseSignature(sig: Uint8Array): RecoveredSignature | null {
249	  const b = Buffer.from(sig);
250	  if (b.length !== 65) return null;
251	  const r = bytesToBigInt(b.subarray(0, 32));
252	  const s = bytesToBigInt(b.subarray(32, 64));
253	  const recoveryId = b.readUInt8(64);
254	  if (r <= 0n || r >= N || s <= 0n || s >= N) return null;
255	  if (s > HALF_N) return null; // 拒绝 high-s（可塑性签名）
256	  if (recoveryId > 3) return null;
257	  return { r, s, recoveryId };
258	}
259	
260	/**
261	 * 由摘要与 65 字节签名恢复签名者未压缩公钥（65 字节）。
262	 * 签名必须 low-s；恢复标识非法或点不在曲线上时返回 null。
263	 */
264	export function recoverPublicKey(digest: Uint8Array, signature: Uint8Array): Buffer | null {
265	  const parsed = parseSignature(signature);
266	  if (parsed === null) return null;
267	  const { r, s, recoveryId } = parsed;
268	  if (digest.length !== 32) return null;
269	
270	  const e = bytesToBigInt(digest) % N;
271	  // recoveryId 高位 j=1 表示 R.x = r + N（曲线阶）；低位为 y 的奇偶
272	  const x = r + ((recoveryId >> 1) === 1 ? N : 0n);
273	  const R = decompressPoint(x, (recoveryId & 1) === 1);
274	  if (R === null) return null;
275	
276	  const rInv = invMod(r, N);
277	  // Q = r^-1 (s R - e G)
278	  const sR = scalarMul(modN(s), R);
279	  const negEG = scalarMul(modN(-e), G);
280	  const negEGAffine = toAffine(negEG);
281	  const sum = negEGAffine === null ? sR : jacAddAffine(sR, negEGAffine);
282	  const Q = toAffine(scalarMulPoint(rInv, sum));
283	  if (Q === null) return null;
284	  return Buffer.concat([Buffer.from([0x04]), to32(Q.x), to32(Q.y)]);
285	}
286	
287	/** 由摘要与 65 字节签名恢复签名者地址 */
288	export function recoverAddress(digest: Uint8Array, signature: Uint8Array): Address | null {
289	  const pub = recoverPublicKey(digest, signature);
290	  return pub === null ? null : addressFromPublicKey(pub);
291	}
292	
293	/** Jacobian 点的标量乘（恢复时 rInv 作用于加和点） */
294	function scalarMulPoint(k: bigint, point: Jacobian): Jacobian {
295	  const affine = toAffine(point);
296	  if (affine === null) return null;
297	  return scalarMul(k, affine);
298	}
299	
300	// ---------- 签名 ----------
301	
302	export interface SignedDigest {
303	  /** 65 字节 r || s || v */
304	  signature: Buffer;
305	}
306	
