3	import { ExecutionQueue } from '../src/queue.ts';
4	import { InvalidQueueStateError, PolicyConflict, TaskNotFoundError } from '../src/errors.ts';
5	
6	function makeQueue(exec?: (t: any) => unknown) {
7	  const calls: string[] = [];
8	  const queue = new ExecutionQueue<any>(
9	    exec ??
10	      ((t) => {
11	        calls.push(t.id);
12	        return { ok: true, id: t.id };
13	      }),
14	  );
15	  return { queue, calls };
16	}
17	
18	function enq(queue: ExecutionQueue<any>, seq: number, digest?: string) {
19	  return queue.enqueue({
20	    nonce: BigInt(seq),
21	    digest: digest ?? `d-${seq}`,
22	    payload: { seq },
23	    submittedAt: 1000n,
24	  });
25	}
26	
27	test('FIFO：按入队顺序排列，队首优先执行', () => {
28	  const { queue, calls } = makeQueue();
29	  const a = enq(queue, 0);
30	  const b = enq(queue, 1);
31	  const c = enq(queue, 2);
32	  assert.deepEqual(queue.listTasks().map((t) => t.seq), [0, 1, 2]);
33	
34	  assert.equal(queue.peekHead()!.id, a.id);
35	  queue.executeNext(1n);
36	  assert.equal(calls[0], a.id);
37	  queue.executeNext(1n);
38	  assert.equal(calls[1], b.id);
39	  queue.executeNext(1n);
40	  assert.equal(calls[2], c.id);
41	  assert.equal(queue.executeNext(1n), null);
