import { test } from 'node:test';
import assert from 'node:assert/strict';
import { MultiSigWallet } from '../src/wallet.ts';
import {
  InvalidPolicyChange,
  InvalidTransaction,
  NonceAlreadyUsedError,
  RequestExpired,
