    InvalidPolicyChange,
  );
  assert.throws(
    () => new MultiSigWallet({ id: 'w', owners: [a.address, b.address], confirmations: 0n }),
    InvalidPolicyChange,
  );
  assert.throws(
    () => new MultiSigWallet({ id: 'w', owners: [a.address, b.address], confirmations: 3n }),
    InvalidPolicyChange,
  );
});

