  const c = enq(queue, 2);
  queue.cancel(b.id, { nonce: 9n, digest: 'x', cancelledAt: 1n }, 1n);
  assert.deepEqual(queue.listTasks().map((t) => t.seq), [0, 1, 2]);
  assert.equal(queue.peekHead()!.id, a.id); // 队首仍是 a
  assert.equal(queue.getTask(c.id)!.status, 'queued');
